# A tiny eval: run a "model" on test cases and score it automatically.

def model_v1(question):
    # Pretend LLM: a fixed lookup with a few mistakes
    answers = {"capital of France": "Paris", "2 + 2": "4",
               "largest planet": "Saturn", "color of the sky": "blue"}
    return answers.get(question, "I am not sure")

def model_v2(question):
    # "Improved prompt" version: fixes one bug
    answer = model_v1(question)
    return "Jupiter" if question == "largest planet" else answer

test_cases = [
    {"q": "capital of France", "expected": "paris"},
    {"q": "2 + 2", "expected": "4"},
    {"q": "largest planet", "expected": "jupiter"},
    {"q": "color of the sky", "expected": "blue"},
    {"q": "speed of light", "expected": "299,792 km/s"},
]

def run_eval(model):
    passed = 0
    for case in test_cases:
        output = model(case["q"])
        ok = case["expected"] in output.lower()   # simple code-based check
        passed += ok
        print(f"  {'PASS' if ok else 'FAIL'}  {case['q']!r:22} -> {output}")
    return passed / len(test_cases)

for name, model in [("v1", model_v1), ("v2", model_v2)]:
    print(f"Model {name}:")
    print(f"  pass rate = {run_eval(model):.0%}\n")
